  #[using="Hvsp Hplen Hsp LEN CFG PL CALLS"] Lemma mem_pw_frame : forall vals M log (a : Z),
    vals_ev vals 0 = sp0 -> log_in_b 0 (2 ^ 40) (2 ^ 40) [] [] IMG_PW log = true ->
    (0 <= a)%Z -> ~ CPpw a ->
    mem_denot (ENVb vals) M log (Z_to_bv 64 a) = M (Z_to_bv 64 a).
Proof.
