  #[using="scfg L HIok Hvsp Hplen DL Lay DLL LIokX Hsp LEN CFG PL CALLS"] Lemma block_pw : forall vals M log LB cr VM g,
    vals_ev vals 0 = sp0 ->
    log_in_b 0 (2 ^ 40) (2 ^ 40) [] [] IMG_PW log = true -> log_below_b 0 0xee000 log = true ->
    (hi_heap HI LB cr M VM -> hi_heap HI LB cr (mem_denot (ENVb vals) M log) VM)
    /\ (above M -> above (mem_denot (ENVb vals) M log))
    /\ (ls_ok LSt g M -> ls_ok LSt g (mem_denot (ENVb vals) M log))
    /\ (forall (a : Z) n bs, hz sp0 a (Z.of_nat n) ->
